payload:
$ErrorActionPreference='Stop'
$src='C:\Users\Xxkan\actions-runner-heaven\_work\mhw-mods\mhw-mods'
git -C $src fetch origin main --prune
if($LASTEXITCODE -ne 0){ throw 'fetch failed' }
$sha=(git -C $src rev-parse origin/main).Trim()
$wt="C:\Users\Xxkan\HeavenBridge\work\qa-main-$($sha.Substring(0,8))"
if(Test-Path $wt){ git -C $src worktree remove --force $wt 2>$null; Remove-Item -Recurse -Force $wt -ErrorAction SilentlyContinue }
git -C $src worktree add --detach $wt $sha
if($LASTEXITCODE -ne 0){ throw 'worktree add failed' }
try {
  Push-Location $wt
  $env:DOTNET_NOLOGO='1'; $env:DOTNET_CLI_TELEMETRY_OPTOUT='1'
  dotnet restore .\MhwModManager.sln -p:NuGetAudit=false
  if($LASTEXITCODE -ne 0){ throw 'restore failed' }
  dotnet build .\MhwModManager.sln -c Release --no-restore -warnaserror -p:NuGetAudit=false
  if($LASTEXITCODE -ne 0){ throw 'build failed' }
  dotnet test .\tests\MhwModManager.Tests\MhwModManager.Tests.csproj -c Release --no-build --no-restore -p:NuGetAudit=false
  if($LASTEXITCODE -ne 0){ throw 'core tests failed' }
  dotnet test .\tests\MhwModManager.AutomationTests\MhwModManager.AutomationTests.csproj -c Release --no-build --no-restore -p:NuGetAudit=false
  if($LASTEXITCODE -ne 0){ throw 'automation tests failed' }
  dotnet test .\tests\MhwModManager.IntegrationTests\MhwModManager.IntegrationTests.csproj -c Release --no-build --no-restore -p:NuGetAudit=false
  if($LASTEXITCODE -ne 0){ throw 'integration tests failed' }
  .\scripts\Test-AgentHandoff.ps1
  if($LASTEXITCODE -ne 0){ throw 'handoff preflight failed' }
  git diff --check
  if($LASTEXITCODE -ne 0){ throw 'diff check failed' }
  Write-Output "MAIN_SHA=$sha"
  Write-Output 'MAIN_BROAD_REGRESSION=PASS'
} finally {
  Pop-Location
  git -C $src worktree remove --force $wt 2>$null
}
